const mockPayload = {
  "conversation_target": {
    "phone_number": "+1234567890",
    "user_id": "user_123", 
    "name": "John Doe"
  },
  "conversation_config": {
    "goal": "collect_product_feedback",
    "prompt": "Collect detailed feedback about our new mobile app including rating, specific features used, and improvement suggestions",
    "max_turns": 8,
    "timeout_hours": 24,
    "conversation_id": "conv_" + Date.now()
  },
  "context": {
    "product_name": "MobileApp Pro",
    "purchase_date": "2025-01-15",
    "previous_interactions": []
  },
  "callback_config": {
    "webhook_url": "https://your-flask-app.com/api/conversation-complete",
    "auth_token": "bearer_token_here"
  }
};

return [{ json: mockPayload }];

// Extract the key information from the payload
const payload = $input.first().json;

// Extract recipient information
const recipient = {
  phone: payload.conversation_target.phone_number,
  userId: payload.conversation_target.user_id,
  name: payload.conversation_target.name
};

// Extract goal and prompt information
const conversationGoal = {
  goal: payload.conversation_config.goal,
  prompt: payload.conversation_config.prompt,
  maxTurns: payload.conversation_config.max_turns,
  conversationId: payload.conversation_config.conversation_id
};

// Extract context for personalization
const context = payload.context;

// Return structured data for next steps
return [{
  json: {
    recipient: recipient,
    conversationGoal: conversationGoal,
    context: context,
    originalPayload: payload // Keep original for reference
  }
}];
